def generate_gcc_options():
    gcc_dir = os.path.join(GCC404_TREE, "gcc")
    gather = os.path.join(gcc_dir, "opt-gather.awk")
    funcs = os.path.join(gcc_dir, "opt-functions.awk")
    optc = os.path.join(gcc_dir, "optc-gen.awk")
    opth = os.path.join(gcc_dir, "opth-gen.awk")
    common = os.path.join(gcc_dir, "common.opt")
    copt = os.path.join(gcc_dir, "c.opt")
    gathered = subprocess.check_output(
        ["awk", "-f", gather, common, copt]
    )
    options_c = subprocess.check_output(
        ["awk", "-f", funcs, "-f", optc],
        input=gathered,
    )
    options_h = subprocess.check_output(
        ["awk", "-f", funcs, "-f", opth],
        input=gathered,
    )
    return options_c, options_h


def generate_gtyp_gen_h():
    # Order matches gcc-4.0.4 gcc/Makefile.in GTFILES so typedefs exist
    # before the .c files that use them (htab_t, splay_tree, cpp_token).
    lines = [
        "/* Generated for Kronos gengtype. */\n",
        'static const char *const srcdir = "/src/gcc";\n',
        "static const char *const lang_files[] = {\n",
        '  "/src/gcc/c-lang.c",\n',
        '  "/src/gcc/c-parse.in",\n',
        '  "/src/gcc/c-tree.h",\n',
        '  "/src/gcc/c-decl.c",\n',
        '  "/src/gcc/c-common.c",\n',
        '  "/src/gcc/c-common.h",\n',
        '  "/src/gcc/c-pragma.c",\n',
        '  "/src/gcc/c-objc-common.c",\n',
        "  0\n};\n",
        "static const char *const langs_for_lang_files[] = {\n",
        '  "c", "c", "c", "c", "c", "c", "c", "c", 0\n};\n',
        "static const char *const all_files[] = {\n",
        '  "/src/gcc/input.h",\n',
        '  "/src/gcc/coretypes.h",\n',
        '  "/src/gcc/libcpp/include/line-map.h",\n',
        '  "/src/gcc/libcpp/include/cpplib.h",\n',
        '  "/src/gcc/libcpp/include/cpp-id-data.h",\n',
        '  "/src/gcc/include/hashtab.h",\n',
        '  "/src/gcc/include/splay-tree.h",\n',
    ]
    skip = {"input.h", "coretypes.h"}
    for name in GTFILES_BASENAMES:
        if name in skip:
            continue
        lines.append('  "/src/gcc/%s",\n' % name)
        if name == "tree.h":
            lines.append('  "/src/gcc/libcpp/include/symtab.h",\n')
    lines.append("  0\n};\n")
    lines.append('static const char *const lang_dir_names[] = { "c", 0 };\n')
    return "".join(lines).encode("ascii")


